import React, { useMemo, useState, useEffect } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
} from "recharts";

/* ======================= */
/* 👇 UI 확인용 임시 데이터 */
/* ======================= */
const DEBUG_USE_MOCK = true; // ✅ UI 확인 끝나면 false 또는 해당 블록 삭제
const MOCK_WEEK = [
  // 오래된 날 → 오늘 순서(7개)
  { fasting: 95, breakfastPost: 122, lunchPost: 138, dinnerPost: 130 },
  { fasting: 98, breakfastPost: 128, lunchPost: 142, dinnerPost: 135 },
  { fasting: 92, breakfastPost: 118, lunchPost: 136, dinnerPost: 127 },
  { fasting: 101, breakfastPost: 133, lunchPost: 149, dinnerPost: 141 },
  { fasting: 97, breakfastPost: 124, lunchPost: 140, dinnerPost: 134 },
  { fasting: 105, breakfastPost: null, lunchPost: 152, dinnerPost: 145 }, // 일부 null로 연결 확인
  { fasting: 99, breakfastPost: 120, lunchPost: null, dinnerPost: 129 },
];

/**
 * props
 * - weekData: [{ day, breakfastPost?, lunchPost?, dinnerPost?, fasting? }]
 * - mode: "post" | "fasting"
 * - height: number
 */
export default function WeeklyGlucoseSlider({
  weekData = [],
  mode = "post",
  height = 360,
  className = "",
}) {
  const [innerMode, setInnerMode] = useState(mode);
  useEffect(() => setInnerMode(mode), [mode]);

  // ✅ 오늘 날짜 (항상 마지막에 배치)
  const today = new Date();

  // ✅ UI 확인을 위해 데이터 소스 결정
  const sourceRows = useMemo(() => {
    if (DEBUG_USE_MOCK) return MOCK_WEEK;
    return Array.isArray(weekData) && weekData.length ? weekData : [];
  }, [weekData]);

  // ✅ 7일간 데이터 + 날짜/요일 라벨링
  const data = useMemo(() => {
    return sourceRows.map((r, idx) => {
      const d = new Date();
      d.setDate(today.getDate() - (6 - idx));
      const month = d.getMonth() + 1;
      const date = d.getDate();
      const weekday = ["일", "월", "화", "수", "목", "금", "토"][d.getDay()];

      return {
        ...r,
        // 라벨은 "8/31 일" 같이 저장, Tick에서 두 줄로 분리
        day: `${month}/${date} ${weekday}`,
      };
    });
  }, [sourceRows]);

  // ✅ Y축: 항상 [60, 200] 이상 고정
  const yDomain = useMemo(() => {
    const vals = data
      .flatMap((d) => [d.breakfastPost, d.lunchPost, d.dinnerPost, d.fasting])
      .filter(isNum);
    if (!vals.length) return [60, 200]; // 데이터 없을 때도 축은 고정
    const min = Math.min(...vals),
      max = Math.max(...vals),
      pad = 10;
    return [
      Math.max(60, Math.floor((min - pad) / 10) * 10),
      Math.ceil((max + pad) / 10) * 10,
    ];
  }, [data]);

  // ✅ X축 Tick 커스텀 (월/일 위줄, (요일) 아래줄)
  const CustomTick = ({ x, y, payload, index }) => {
    if (!payload?.value) return null;

    const [date, weekday] = payload.value.split(" ");

    // ✅ 날짜별 값 유무 판정 (현재 사용 중인 sourceRows 기준)
    const row = sourceRows[index] || {};
    let isEmpty = false;

    if (innerMode === "post") {
      isEmpty =
        row?.breakfastPost == null &&
        row?.lunchPost == null &&
        row?.dinnerPost == null;
    } else if (innerMode === "fasting") {
      isEmpty = row?.fasting == null;
    }

    const color = isEmpty ? "#9ca3af" : "#475569"; // 회색 or 기본색

    return (
      <g transform={`translate(${x},${y + 10})`}>
        <text
          x={0}
          y={0}
          textAnchor="middle"
          fill={color}
          fontSize={11}
          fontWeight={600}
        >
          {date}
        </text>
        <text x={0} y={14} textAnchor="middle" fill={color} fontSize={11}>
          ({weekday})
        </text>
      </g>
    );
  };

  return (
    <section className={className} style={{ width: "100%" }}>
      <div style={{ width: "100%", height, marginTop: -70 }}>
        {innerMode === "post" ? (
          <ResponsiveContainer width="100%" height="100%">
            <LineChart
              data={data}
              margin={{ top: 100, right: 12, left: -20, bottom: 50 }}
            >
              <CartesianGrid
                stroke="#94a3b8"
                strokeOpacity={0.25}
                strokeDasharray="4 6"
              />
              <XAxis
                dataKey="day"
                tick={<CustomTick />}
                interval={0}
                padding={{ left: 20, right: 20 }}
              />
              <YAxis
                domain={yDomain}
                tickCount={6}
                tick={{ fontSize: 12, fill: "#475569" }}
                tickMargin={7}
              />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="breakfastPost"
                name="아침 식후"
                stroke="#3b82f6"
                strokeWidth={3.5}
                dot={(props) =>
                  props.index === 0 ? <circle r={4} {...props} /> : null
                }
                activeDot={{ r: 5 }}
                connectNulls
              />
              <Line
                type="monotone"
                dataKey="lunchPost"
                name="점심 식후"
                stroke="#10b981"
                strokeWidth={3.5}
                dot={(props) =>
                  props.index === 0 ? <circle r={4} {...props} /> : null
                }
                activeDot={{ r: 5 }}
                connectNulls
              />
              <Line
                type="monotone"
                dataKey="dinnerPost"
                name="저녁 식후"
                stroke="#ef4444"
                strokeWidth={3.5}
                dot={(props) =>
                  props.index === 0 ? <circle r={4} {...props} /> : null
                }
                activeDot={{ r: 5 }}
                connectNulls
              />
            </LineChart>
          </ResponsiveContainer>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={data}
              margin={{ top: 100, right: 12, left: -20, bottom: 50 }}
            >
              <CartesianGrid
                stroke="#94a3b8"
                strokeOpacity={0.25}
                strokeDasharray="4 6"
              />
              <XAxis dataKey="day" tick={<CustomTick />} interval={0} />
              <YAxis
                domain={yDomain}
                tickCount={6}
                tick={{ fontSize: 12, fill: "#475569" }}
                tickMargin={7}
              />
              <Tooltip />
              <Bar
                dataKey="fasting"
                name="공복"
                fill="#6366f1"
                radius={[8, 8, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        )}
      </div>
    </section>
  );
}

function isNum(n) {
  return typeof n === "number" && Number.isFinite(n);
}
