// src/pages/diet/components/mealplan/MealSectionSlider.jsx

import React, { useState, useEffect } from "react";
import MealSectionHeader from "./MealSectionHeader";
import MealItemList from "./MealItemList";
import MealRefreshModal from "./MealRefreshModal";
import "./MealSection.css";
import { FaChevronRight, FaChevronLeft } from "react-icons/fa";
import axios from "axios";

function MealSection({ mealData, setMealData }) {
  const mealTypes = [
    { label: "아침", key: "breakfastMeal", icon: "☀️", oneTime: 0 },
    { label: "점심", key: "lunchMeal", icon: "🌤️", oneTime: 1 },
    { label: "저녁", key: "dinnerMeal", icon: "🌙", oneTime: 2 },
  ];

  const [currentIndex, setCurrentIndex] = useState(0);
  const currentMeal = mealTypes[currentIndex];
  // 새로고침 모달 상태
  const [showModal, setShowModal] = useState(false);
  // 🔥 새로고침 로딩 상태
  const [isRefreshing, setIsRefreshing] = useState(false);
  // 🔥 mealData 바뀔 때마다 currentIndex를 초기화 (아침으로)

  // 날짜가 바뀔 때만 currentIndex 초기화
  useEffect(() => {
    if (mealData?.date) {
      setCurrentIndex(0);
    }
  }, [mealData?.date]);
  const handleNext = () => {
    setCurrentIndex((prev) => (prev + 1) % mealTypes.length);
  };

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev - 1 + mealTypes.length) % mealTypes.length);
  };

  const handleRefreshClick = () => {
    setShowModal(true);
  };

  const handleConfirmRefresh = async () => {
    setShowModal(false); // 모달 닫기
    setIsRefreshing(true); // 로딩 시작
    try {
      const res = await axios.post(
        "/api/model/diet/one",
        {
          date: mealData.date, // 현재 선택된 날짜
          oneTime: currentMeal.oneTime, // 현재 탭(아침/점심/저녁)
        },
        { withCredentials: true }
      );
      console.log("새로고침 응답:", res.data);

      // mealData 갱신
      setMealData((prev) => ({
        ...prev,
        [currentMeal.key]: res.data, // 해당 끼니만 교체
      }));
    } catch (err) {
      console.error("식단 새로고침 실패:", err);
    } finally {
      setIsRefreshing(false); // 로딩 종료
    }
  };

  return (
    <div className="meal-section-slider">
      <div className="slider-wrapper">
        {currentIndex > 0 && (
          <button className="nav-btn left" onClick={handlePrev}>
            <FaChevronLeft />
          </button>
        )}

        <div className="meal-section">
          <MealSectionHeader
            label={currentMeal.label}
            icon={currentMeal.icon}
            onRefresh={handleRefreshClick}
            // onRefresh={() => console.log("새로고침 API 연결")}
          />

          {/* <MealItemList items={currentMeal.items} className="meal-scroll" /> */}
          <div
            className={`meal-items-area ${
              (mealData[currentMeal.key]?.length || 0) <= 3
                ? "center-mode"
                : "scroll-mode"
            }`}
          >
            <MealItemList
              items={mealData[currentMeal.key]}
              loading={isRefreshing}
            />
          </div>

          <MealRefreshModal
            visible={showModal}
            onClose={() => setShowModal(false)}
            onConfirm={handleConfirmRefresh}
          />
        </div>

        {currentIndex < mealTypes.length - 1 && (
          <button className="nav-btn right" onClick={handleNext}>
            <FaChevronRight />
          </button>
        )}
      </div>
    </div>
  );
}

export default MealSection;
