import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./transrecipe.css";
import axios from "axios";

import illustration from "../../../assets/kangaroo_trans_illustration.png";
import Header from "../../../components/Header";

export default function TransRecipe() {
  const nav = useNavigate();
  const [url, setUrl] = useState("");

  const onSubmit = async (e) => {
    e.preventDefault();
    const clean = (url || "").trim();
    if (!clean) {
      alert("레시피 링크를 입력해주세요!");
      return;
    }
    //  API 호출은 하지 않고 URL만 전달
    nav("/transrecipe/loading", { state: { url: clean } });
  };

  return (
    <div className="app-wrap">
      <div className="app">
        <Header title={"레시피 변환"} className="trp-header" />
        {/* ← 타이틀 없이 뒤로가기만 */}
        <div className="trp-screen">
          {/* 상단 영역 */}
          <header className="trp-top">
            <img
              src={illustration}
              alt="변환 절차 일러스트"
              className="trp-illust"
            />
          </header>

          {/* 하단 카드 */}
          <section className="trp-bottom">
            {/* <h1 className="trp-title">저당 레시피 변환</h1> */}

            {/* 단계 표시 */}
            <div className="trp-steps">
              <div className="step url">
                <span className="icon">✔</span>
                <span className="label">url 입력</span>
              </div>
              <div className="arrow">→</div>
              <div className="step analysis">
                <span className="icon">⚙</span>
                <span className="label">레시피 분석</span>
              </div>
              <div className="arrow">→</div>
              <div className="step result">
                <span className="icon">🍲</span>
                <span className="label">저당 레시피 완성</span>
              </div>
            </div>

            {/* 설명 */}
            <p className="trp-desc">
              원하는 레시피가 담긴 링크를 입력해보세요!
              <br />
              당당이가 분석해서 저당 레시피로 바꿔드립니다!
            </p>

            {/* 입력 */}
            <form className="trp-form" onSubmit={onSubmit}>
              <input
                className="trp-input"
                type="url"
                placeholder="https://..."
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                required
              />
              <button type="submit" className="trp-submit">
                변환하기
              </button>
            </form>
          </section>
        </div>
      </div>
    </div>
  );
}
