  //   let start = null;

  //   const ease = (t) => 1 - Math.pow(1 - t, 3);

  //   const tick = (ts) => {
  //     if (start == null) start = ts;
  //     const raw = Math.min(1, (ts - start) / durationRef.current);
  //     const eased = ease(raw);

  //     const pct = raw < 1 ? Math.floor(eased * 100) : 100;
  //     setProgress(pct);

  //     if (pct < 100) {
  //       rafId = requestAnimationFrame(tick);
  //     } else {
  //       requestAnimationFrame(() => {
  //         if (typeof onDoneRef.current === "function") onDoneRef.current();
  //         if (autoNavRef.current) nav(autoNavRef.current); // ✅ 100% 되면 이동
